const formData = $('On form submission').first().json;
const currentFolder = formData.folder;
const folderMatch = currentFolder.match(/^agent_(\d+)\//);
const agentId = folderMatch ? parseInt(folderMatch[1]) : 1;

return $input.all()
  .filter(item => {
    const key = item.json.Key || item.json.key || '';
    return key.startsWith(currentFolder) && key.endsWith('.md') && !key.endsWith('/');
  })
  .map(item => {
    const rawKey = item.json.Key || item.json.key || '';
    return {
      json: {
        Key:          rawKey,
        s3Key:        rawKey,
        rawKey:       rawKey,
        fileName:     rawKey.split('/').pop(),
        folder:       currentFolder,
        agent_id:     agentId,
        block_number: agentId
      }
    };
  });

const binaryData = $binary?.data;
if (!binaryData) {
  throw new Error('No binary data found');
}

// n8n stores file content as base64 in binaryData.data
// but for text files it might be in different encoding
const content = binaryData.data 
  ? Buffer.from(binaryData.data, binaryData.encoding || 'base64').toString('utf-8')
  : await this.helpers.getBinaryDataBuffer(0, 'data').then(b => b.toString('utf-8'));

return [{
  json: {
    ...$json,
    rawMarkdown: content
  }
}];

const content = $json.rawMarkdown || '';

let metadata = {};
let bodyContent = content;

const frontmatterMatch = content.match(/^---\s*\n([\s\S]*?)\n---\s*\n([\s\S]*)$/m);
if (frontmatterMatch) {
  const yamlBlock = frontmatterMatch[1];
  bodyContent = frontmatterMatch[2];
  const lines = yamlBlock.split('\n');
  for (const line of lines) {
    const match = line.match(/^([\w_]+):\s*(.*)$/);
    if (match) {
      const key = match[1].trim();
      let val = match[2].trim().replace(/^"|"$/g, '').replace(/^'|'$/g, '');
      metadata[key] = val;
    }
  }
}

const fileName = $json.fileName || '';
const baseName = fileName.replace('.md', '');
const agentId = $json.agent_id || 0;
const blockNumber = $json.block_number || agentId;

return [{
  json: {
    ...$json,
    bodyContent: bodyContent.trim(),
    metadata: {
      title:        metadata.title || baseName,
      authors:      metadata.authors || metadata.author || '',
      year:         parseInt(metadata.year) || null,
      type:         metadata.type || 'document',
      topic:        metadata.topic || '',
      language:     metadata.language || 'de',
      source_file:  $json.rawKey || $json.Key || '',
      bucket:       'vhb-rag',
      doc_type:     (metadata.type === 'interview' || metadata.type === 'transkript')
                      ? 'interview'
                      : metadata.type === 'wissensbausteine'
                        ? 'wissensbausteine'
                        : metadata.type === 'vorlesung'
                          ? 'vorlesung'
                          : 'document',
      agent_id:     agentId,
      block_number: blockNumber
    }
  }
}];

const content = $json.bodyContent || '';
const meta = $json.metadata || {};
const docType = meta.doc_type || 'document';

const CHUNK_SIZE = 600;
const CHUNK_OVERLAP = 80;
const WORDS_PER_TOKEN = 0.75;
const MAX_WORDS = Math.floor(CHUNK_SIZE * WORDS_PER_TOKEN);
const OVERLAP_WORDS = Math.floor(CHUNK_OVERLAP * WORDS_PER_TOKEN);

function cyrb53(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1>>>16), 2246822507) ^ Math.imul(h2 ^ (h2>>>13), 3266489909);
  h2 = Math.imul(h2 ^ (h2>>>16), 2246822507) ^ Math.imul(h1 ^ (h1>>>13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1>>>0)).toString(16);
}

const extractEffectSize = (text) => {
  const m = (text || '').match(/\bd\s*[=:]\s*(\d+[,.]\d+)/);
  return m ? parseFloat(m[1].replace(',', '.')) : null;
};

const chunks = [];
const now = new Date().toISOString();

// ─── PFAD 1: INTERVIEW ───────────────────────────────────────────────────────
if (docType === 'interview') {
  const speakerBlockRegex = /###\s+(.+?)\n<!--\s*ts:\s*([\d:]+)-([\d:]+)\s*-->\n([\s\S]*?)(?=###|$)/g;
  let match;
  let idx = 0;
  while ((match = speakerBlockRegex.exec(content)) !== null) {
    const speaker  = match[1].trim();
    const ts_start = match[2].trim();
    const ts_end   = match[3].trim();
    const text     = match[4].trim();
    if (text.length < 20) continue;
    chunks.push({
      text, speaker, ts_start, ts_end,
      section: '', page_number: null,
      speaker_count: 0, chunk_index: idx++,
      chapter_title: '', parent_chapter_title: '',
      section_type: null, effect_size: null,
      wb_section: null
    });
  }
  const uniqueSpeakers = new Set(chunks.map(c => c.speaker)).size;
  chunks.forEach(c => c.speaker_count = uniqueSpeakers);
}

// ─── PFAD 2: WISSENSBAUSTEINE ─────────────────────────────────────────────────
else if (docType === 'wissensbausteine') {

  const CHAPTER_RE = /^##\s+(\d+)\.(\d+(?:\.\d+)*)\.?\s+(.+)$/;
  const SECTION_RE = /^##\s+(.+)$/;

  const PARENT_CHAPTERS = {
    '1': 'Was bieten die Wissensbausteine?',
    '2': 'Grundbegriffe der Mediendidaktik',
    '3': 'Digitale Kompetenzen von Lehrkräften',
    '4': 'Kognitive Lernvoraussetzungen',
    '5': 'Motivational-affektive Lernvoraussetzungen',
    '6': 'Kompetenzen und Lernergebnisse',
    '7': 'Unterrichtsmethoden',
    '8': 'Lehrtechniken',
    '9': 'Lernen in adaptiven digitalen Lernumgebungen'
  };

  const getSectionType = (heading) => {
    const h = (heading || '').toLowerCase();
    if (/gestaltungshinweis/.test(h))       return 'design_hints';
    if (/wirksamkeit/.test(h))              return 'effectiveness';
    if (/phasenverlauf|ablauf/.test(h))     return 'mechanism';
    if (/^was ist|^definition/.test(h))     return 'definition';
    if (/studie|beispiel|exkurs/.test(h))   return 'example_box';
    return 'content';
  };

  const lines = content.split('\n');
  let chunkIndex = 0;

  let currentChapterTitle = '';
  let currentParentTitle  = '';
  let currentSectionTitle = '';
  let currentWbSection    = '';   // NEU: z.B. "4.2"
  let currentLines        = [];

  const flushChunk = () => {
    const text  = currentLines.join('\n').trim();
    const words = text.split(/\s+/).filter(w => w.length > 0);
    if (words.length < 20) return;

    const sectionLabel = (currentSectionTitle && currentSectionTitle !== currentChapterTitle)
      ? ` [${currentSectionTitle}]`
      : '';
    const prefixedText = `${currentChapterTitle}${sectionLabel}: ${text}`;

    chunks.push({
      text:                 prefixedText,
      section:              currentSectionTitle || currentChapterTitle,
      chapter_title:        currentChapterTitle,
      parent_chapter_title: currentParentTitle,
      wb_section:           currentWbSection,   // NEU
      section_type:         getSectionType(currentSectionTitle || currentChapterTitle),
      effect_size:          extractEffectSize(text),
      speaker:              null,
      ts_start:             null,
      ts_end:               null,
      speaker_count:        null,
      page_number:          null,
      chunk_index:          chunkIndex++
    });
  };

  for (const line of lines) {
    const chapterMatch = line.match(CHAPTER_RE);
    if (chapterMatch) {
      flushChunk();
      currentLines        = [];
      const parentNum     = chapterMatch[1];
      const subNum        = chapterMatch[2];
      currentChapterTitle = chapterMatch[3].trim();
      currentParentTitle  = PARENT_CHAPTERS[parentNum] || '';
      currentWbSection    = `${parentNum}.${subNum}`;  // NEU: z.B. "4.2"
      currentSectionTitle = currentChapterTitle;
      continue;
    }

    if (currentChapterTitle) {
      const sectionMatch = line.match(SECTION_RE);
      if (sectionMatch) {
        flushChunk();
        currentLines        = [];
        currentSectionTitle = sectionMatch[1].trim();
        continue;
      }
      currentLines.push(line);
    }
  }
  flushChunk();
}

// ─── PFAD 3: DOCUMENT / VORLESUNG ────────────────────────────────────────────
else {
  const lines = content.split('\n');
  let currentSection    = '';
  let currentPageNumber = null;
  let wordBuffer        = [];
  let chunkIndex        = 0;

  const flushChunk = (words, section, page) => {
    if (words.length < 10) return;
    const text = words.join(' ');
    chunks.push({
      text, speaker: null, ts_start: null, ts_end: null,
      section, page_number: page, speaker_count: null,
      chunk_index: chunkIndex++,
      chapter_title: '', parent_chapter_title: '',
      wb_section: null,
      section_type: null,
      effect_size: extractEffectSize(text)
    });
  };

  for (const line of lines) {
    const headingMatch = line.match(/^#{2,3}\s+(.+)$/);
    if (headingMatch) {
      if (wordBuffer.length >= 10) {
        flushChunk(wordBuffer, currentSection, currentPageNumber);
        wordBuffer = [];
      }
      currentSection = headingMatch[1].trim();
      continue;
    }

    const pageMatch = line.match(/<!--\s*page\s+(\d+)\s*-->/);
    if (pageMatch) {
      currentPageNumber = parseInt(pageMatch[1]);
      continue;
    }

    const words = line.split(/\s+/).filter(w => w.length > 0);
    wordBuffer.push(...words);

    if (wordBuffer.length >= MAX_WORDS) {
      flushChunk(wordBuffer.slice(0, MAX_WORDS), currentSection, currentPageNumber);
      wordBuffer = wordBuffer.slice(MAX_WORDS - OVERLAP_WORDS);
    }
  }

  if (wordBuffer.length >= 10) {
    flushChunk(wordBuffer, currentSection, currentPageNumber);
  }
}

// ─── OUTPUT ───────────────────────────────────────────────────────────────────
const total = chunks.length;

return chunks.map(chunk => ({
  json: {
    text:                 chunk.text,
    doc_type:             meta.doc_type,
    chapter_title:        chunk.chapter_title        || '',
    parent_chapter_title: chunk.parent_chapter_title || '',
    wb_section:           chunk.wb_section           || null,
    section:              chunk.section              || null,
    section_type:         chunk.section_type         || null,
    effect_size:          chunk.effect_size          ?? null,
    speaker:              chunk.speaker              || null,
    ts_start:             chunk.ts_start             || null,
    ts_end:               chunk.ts_end               || null,
    chunk_index:          chunk.chunk_index,
    chunk_total:          total,
    chunk_hash:           cyrb53(meta.source_file + '::' + chunk.chunk_index + '::' + chunk.text.substring(0, 100)),
    speaker_count:        chunk.speaker_count        ?? null,
    page_number:          chunk.page_number          ?? null,
    source_title:         meta.title,
    source_file:          meta.source_file,
    bucket:               meta.bucket,
    language:             meta.language,
    authors:              meta.authors,
    year:                 meta.year                  ?? null,
    type:                 meta.type,
    topic:                meta.topic,
    agent_id:             meta.agent_id,
    block_number:         meta.block_number,
    ingest_date:          now
  }
}));

const chunks = $input.all();
const WEAVIATE_URL = 'http://vhb-weaviate:10100';
const WEAVIATE_KEY = 'Ttcvduoknec98ioUHNiuziGu9ujndK4P';
const OLLAMA_URL = 'http://152.53.85.190:11434';
const BGE_MODEL = 'bge-m3:latest';

let written = 0;
let skipped = 0;
const errors = [];
let debugInfo = null;

for (const item of chunks) {
  const chunk = item.json;

  try {
    // 1. Hash-Check in Weaviate
    const hashRaw = await this.helpers.request({
      method: 'POST',
      url: `${WEAVIATE_URL}/v1/graphql`,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${WEAVIATE_KEY}`
      },
      body: JSON.stringify({
        query: `{ Get { Chunk(where: { path: ["chunk_hash"], operator: Equal, valueText: "${chunk.chunk_hash}" }) { chunk_hash } } }`
      }),
      json: false
    });

    if (debugInfo === null) {
      debugInfo = hashRaw.substring(0, 500);
    }

    const hashParsed = JSON.parse(hashRaw);
    const chunkList = hashParsed?.data?.Get?.Chunk;

    if (chunkList && chunkList.length > 0) {
      skipped++;
      continue;
    }

    // 2. Embedding via bge-m3
    const embedRaw = await this.helpers.request({
      method: 'POST',
      url: `${OLLAMA_URL}/api/embeddings`,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: BGE_MODEL, prompt: chunk.text }),
      json: false
    });
    const embedParsed = JSON.parse(embedRaw);
    const vector = embedParsed.embedding;
    if (!vector || vector.length === 0) {
      errors.push(`No embedding: chunk ${chunk.chunk_index} in ${chunk.source_file}`);
      continue;
    }

    // 3. Write to Weaviate
    await this.helpers.request({
      method: 'POST',
      url: `${WEAVIATE_URL}/v1/objects`,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${WEAVIATE_KEY}`
      },
      body: JSON.stringify({
        class: 'Chunk',
        vector: vector,
        properties: {
          text:                 chunk.text,
          doc_type:             chunk.doc_type,
          chapter_title:        chunk.chapter_title        || '',
          parent_chapter_title: chunk.parent_chapter_title || '',
          wb_section:           chunk.wb_section           || '',
          section:              chunk.section              || '',
          section_type:         chunk.section_type         || '',
          effect_size:          chunk.effect_size          ?? null,
          speaker:              chunk.speaker              || '',
          ts_start:             chunk.ts_start             || '',
          ts_end:               chunk.ts_end               || '',
          chunk_index:          chunk.chunk_index,
          chunk_total:          chunk.chunk_total,
          chunk_hash:           chunk.chunk_hash,
          speaker_count:        chunk.speaker_count        ?? null,
          page_number:          chunk.page_number          ?? null,
          source_title:         chunk.source_title         || '',
          source_file:          chunk.source_file          || '',
          bucket:               chunk.bucket               || '',
          language:             chunk.language             || '',
          authors:              chunk.authors              || '',
          year:                 chunk.year                 ?? null,
          type:                 chunk.type                 || '',
          topic:                chunk.topic                || '',
          agent_id:             chunk.agent_id,
          block_number:         chunk.block_number,
          ingest_date:          chunk.ingest_date
        }
      }),
      json: false
    });
    written++;

  } catch(e) {
    errors.push(`chunk ${chunk.chunk_index} of ${chunk.source_file}: ${e.message}`);
  }
}

const firstChunk = chunks[0]?.json || {};
return [{
  json: {
    s3Key:                firstChunk.source_file || '',
    Key:                  firstChunk.source_file || '',
    fileName:             (firstChunk.source_file || '').split('/').pop(),
    folder:               (firstChunk.source_file || '').split('/')[0] + '/',
    agent_id:             firstChunk.agent_id,
    block_number:         firstChunk.block_number,
    _debug_hash_response: debugInfo,
    _ingest_source_file:  firstChunk.source_file || 'unknown',
    _ingest_chunks_total: chunks.length,
    _ingest_written:      written,
    _ingest_skipped:      skipped,
    _ingest_errors:       errors
  }
}];
